-- Tanaris: creature abilities
-- Most of the zone's creatures (the Wastewander bandits, the Southsea pirates, the Dunemaul ogres, the Sandfury trolls, the silithids, hyenas and basilisks) had no AI or ran classic rows. Port their abilities from the
-- Cataclysm data, and from the classic data where Cataclysm has none, keeping the quest scripts already in place; gossip and quest
-- reward scripts of the references are left out. The creatures no reference scripts cast their sniffed spells (creature_template
-- spell1-8).

SET @ENTRIES := '5420,5426,5427,5429,5430,5431,5450,5451,5452,5454,5455,5458,5459,5460,5465,5475,5645,5646,5647,7855,7858,8197,8198,8199,8200,8203,8204,8205,8207,8667,9397,12124,14123,21448,38648,38649,38650,38719,38749,38880,38909,38914,38916,38997,38998,39020,39022,39061,39081,39183,39185,39186,40527,40581,40593,40632,40635,40636,40648,40657,40717,40764,44546,44557,44568,44569,44587,44594,44598,44599,44611,44612,44613,44714,44722,44750,44759,44761,44767,47386,47387,48130';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '8208,44573,44694,48155,51517';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
